def _getOrCreateSegmentationNode(self):
    nodeName = "CollaborativeSegmentation"
    node = slicer.mrmlScene.GetFirstNodeByName(nodeName)

    if not node:
        # Check if any segmentation node exists to adopt it
        node = slicer.mrmlScene.GetFirstNodeByClass("vtkMRMLSegmentationNode")
        if node:
            node.SetName(nodeName)

def ensureDependencies(self):
    """Checks and installs websocket-client if missing."""
    try:
        import websocket
        self.websocket = websocket
    except ImportError:
        slicer.util.showStatusMessage("Installing websocket dependencies...")
        slicer.util.pip_install("websocket-client")
        import websocket
